import metadata from './block.json';

const { attributes: blockAttributes, supports: blockSupports } = metadata;

type ColumnAttributes = Record< string, unknown > & {
	width?: number | string;
};

/**
 * Deprecation for the numeric `width` attribute, stored as a percentage
 * until the block switched to string values with units.
 *
 * Attribute-only: the markup of that version is regenerated by the parser;
 * only the width needs migrating.
 */
const numericWidth = {
	attributes: {
		...blockAttributes,
		width: {
			type: 'number',
			min: 0,
			max: 100,
		},
	},
	supports: blockSupports,
	isEligible( { width }: ColumnAttributes ) {
		return isFinite( width as number );
	},
	migrate( attributes: ColumnAttributes ) {
		return {
			...attributes,
			width: `${ attributes.width }%`,
		};
	},
};

export default [ numericWidth ];
